INSERT INTO prestaciones(nombre,descripcion,activo) VALUES ('Consulta veterinaria','Evaluación general de tu mascota',true),('Vacunación','Aplicación con evaluación previa',true),('Baño y peluquería','Cuidado e higiene',true) ON CONFLICT(nombre) DO NOTHING;
INSERT INTO sede_prestacion(id_sede,id_prestacion,precio,duracion_minutos,activo) SELECT s.id,p.id,CASE WHEN p.nombre='Consulta veterinaria' THEN 60.00 WHEN p.nombre='Vacunación' THEN 45.00 ELSE 40.00 END,30,true FROM sedes s CROSS JOIN prestaciones p WHERE s.nombre IN ('Garritas Miraflores','Garritas Los Olivos','Garritas Cayma','Garritas Trujillo Centro','Garritas Wanchaq','Garritas El Tambo') AND p.nombre IN ('Consulta veterinaria','Vacunación','Baño y peluquería') ON CONFLICT(id_sede,id_prestacion) DO NOTHING;
